// JAVA MID-TERM PREP - MAIN SCRIPT
var sections = {};
var currentQuizIndex = 0;
var quizScore = 0;
var quizAnswered = false;
var currentMockTest = 0;
var mockTimer = null;
var mockTimeLeft = 0;
var currentFlashcard = 0;

document.addEventListener('DOMContentLoaded', function() {
  initNav();
  loadSection('dashboard');
});

function initNav() {
  var items = document.querySelectorAll('.nav-item');
  for (var i = 0; i < items.length; i++) {
    items[i].addEventListener('click', function() {
      var sec = this.getAttribute('data-section');
      var all = document.querySelectorAll('.nav-item');
      for (var j = 0; j < all.length; j++) all[j].classList.remove('active');
      this.classList.add('active');
      loadSection(sec);
      if (window.innerWidth <= 768) document.getElementById('sidebar').classList.remove('open');
    });
  }
}

function toggleSidebar() {
  document.getElementById('sidebar').classList.toggle('open');
}

function loadSection(id) {
  var main = document.getElementById('mainContent');
  var html = sections[id];
  if (!html) return;
  main.innerHTML = '<div class="section" id="sec-' + id + '">' + html + '</div>';
  if (id === 'quiz') initQuiz();
  if (id === 'mocktest') initMockTest();
  if (id === 'flashcards') initFlashcards();
  updateStats();
  window.scrollTo(0, 0);
}

function toggleAnswer(id) {
  var el = document.getElementById(id);
  if (el) el.classList.toggle('hidden');
}

function updateProgress(cb, key) {
  var p = JSON.parse(localStorage.getItem('java_progress') || '{}');
  if (cb.checked) p[key] = true; else delete p[key];
  localStorage.setItem('java_progress', JSON.stringify(p));
  updateStats();
}

function resetProgress() {
  if (confirm('Reset all progress?')) {
    localStorage.removeItem('java_progress');
    localStorage.removeItem('quiz_score');
    location.reload();
  }
}

function updateStats() {
  var p = JSON.parse(localStorage.getItem('java_progress') || '{}');
  var c = Object.keys(p).length;
  var pct = Math.round((c / 30) * 100);
  var el = document.getElementById('completedTopics');
  if (el) el.textContent = c;
  var pp = document.getElementById('progressPercent');
  if (pp) pp.textContent = pct + '%';
  var pb = document.getElementById('progressBar');
  if (pb) { pb.style.width = pct + '%'; pb.textContent = pct + '%'; }
  var qs = document.getElementById('quizScore');
  if (qs) { var ls = localStorage.getItem('quiz_score'); qs.textContent = ls ? ls + '%' : '0%'; }
}

function handleSearch(q) {
  q = q.toLowerCase().trim();
  if (!q) return;
  var map = {
    'jvm':'notes-jvm','jre':'notes-jvm','jdk':'notes-jvm','jit':'notes-jvm','bytecode':'notes-jvm',
    'string':'notes-string','substring':'notes-stringmethods','concat':'notes-stringmethods','equals':'notes-stringmethods',
    'charat':'notes-stringmethods','indexof':'notes-stringmethods','compareto':'notes-stringmethods',
    'variable':'notes-variable','scope':'notes-variable','constant':'notes-variable',
    'type casting':'notes-casting','casting':'notes-casting','implicit':'notes-casting','explicit':'notes-casting',
    'operator':'notes-operators','arithmetic':'notes-operators','relational':'notes-operators','logical':'notes-operators',
    'control':'notes-control','if-else':'notes-control','for loop':'notes-control','while':'notes-control',
    'array':'notes-array','2d array':'notes-2darray','command line':'notes-cmdargs','args':'notes-cmdargs',
    'class':'notes-classobj','object':'notes-classobj','method':'notes-methods',
    'constructor':'notes-constructors','this':'notes-this','static':'notes-static',
    'garbage':'notes-gc','oop':'notes-oop','polymorphism':'notes-oop','abstraction':'notes-oop',
    'inheritance':'notes-oop','encapsulation':'notes-oop',
    'data type':'notes-datatype','int':'notes-datatype','boolean':'notes-datatype',
    'feature':'notes-history','history':'notes-history','application':'notes-applications',
    'output':'output-practice','program':'programming-practice','quiz':'quiz','mock':'mocktest',
    'flashcard':'flashcards','revision':'revision','strategy':'strategy','hot question':'hot-questions'
  };
  var results = [];
  for (var k in map) {
    if (k.indexOf(q) >= 0 || q.indexOf(k) >= 0) results.push({topic: k, section: map[k]});
  }
  if (!results.length) results.push({topic: 'No results found', section: 'dashboard'});
  var h = '<h1>Search Results for "' + q + '"</h1>';
  for (var i = 0; i < results.length; i++) {
    var r = results[i];
    h += '<div class="card" style="cursor:pointer" onclick="navTo(\'' + r.section + '\')"><strong>' + r.topic + '</strong> - Click to view</div>';
  }
  document.getElementById('mainContent').innerHTML = '<div class="section">' + h + '</div>';
}

function navTo(id) {
  var items = document.querySelectorAll('.nav-item');
  for (var i = 0; i < items.length; i++) {
    items[i].classList.remove('active');
    if (items[i].getAttribute('data-section') === id) items[i].classList.add('active');
  }
  loadSection(id);
}

