function initQuiz() {
  currentQuizIndex = 0;
  quizScore = 0;
  quizAnswered = false;
  renderQuizQ();
}

function renderQuizQ() {
  var el = document.getElementById('quizContainer');
  if (!el) return;
  if (currentQuizIndex >= quizData.length) {
    var pct = Math.round((quizScore / quizData.length) * 100);
    localStorage.setItem('quiz_score', pct);
    el.innerHTML = '<div class="card"><h2>Quiz Complete!</h2><p>Score: <strong>' + quizScore + '/' + quizData.length + '</strong> (' + pct + '%)</p><div class="progress-bar"><div class="progress-fill" style="width:' + pct + '%">' + pct + '%</div></div><p style="margin-top:15px">' + (pct >= 70 ? 'Great job!' : 'Revise weak areas.') + '</p><button class="btn btn-primary" onclick="initQuiz()" style="margin-top:10px">Restart</button></div>';
    return;
  }
  var q = quizData[currentQuizIndex];
  var h = '<div class="card"><p style="font-size:.85rem;color:var(--text-light)">Question ' + (currentQuizIndex+1) + ' of ' + quizData.length + '</p><h3>' + q.q + '</h3><div id="quizOpts">';
  var letters = ['A','B','C','D'];
  for (var i = 0; i < q.o.length; i++) {
    h += '<div class="quiz-option" onclick="answerQuiz(' + i + ')" id="qo' + i + '">' + letters[i] + '. ' + q.o[i] + '</div>';
  }
  h += '</div><div id="quizFb" class="hidden"></div><div id="quizNxt" class="hidden" style="margin-top:10px"><button class="btn btn-primary" onclick="nextQuizQ()">Next</button></div></div>';
  el.innerHTML = h;
  quizAnswered = false;
}

function answerQuiz(sel) {
  if (quizAnswered) return;
  quizAnswered = true;
  var q = quizData[currentQuizIndex];
  var c = q.a;
  document.getElementById('qo' + sel).classList.add(sel === c ? 'correct' : 'wrong');
  if (sel !== c) document.getElementById('qo' + c).classList.add('correct');
  if (sel === c) quizScore++;
  var opts = document.querySelectorAll('.quiz-option');
  for (var i = 0; i < opts.length; i++) opts[i].style.pointerEvents = 'none';
  document.getElementById('quizFb').innerHTML = '<div class="' + (sel === c ? 'tip' : 'warning') + '"><strong>' + (sel === c ? 'Correct!' : 'Wrong!') + '</strong> ' + q.e + '</div>';
  document.getElementById('quizFb').classList.remove('hidden');
  document.getElementById('quizNxt').classList.remove('hidden');
}

function nextQuizQ() {
  currentQuizIndex++;
  renderQuizQ();
}

