function initMockTest() { renderMockList(); }

function renderMockList() {
  var el = document.getElementById('mockContainer');
  if (!el) return;
  var h = '<div class="card"><h2>Available Mock Tests</h2>';
  for (var i = 0; i < mockTests.length; i++) {
    h += '<div style="display:flex;justify-content:space-between;align-items:center;padding:10px;border-bottom:1px solid var(--border)"><div><strong>' + mockTests[i].title + '</strong><br><span style="font-size:.85rem;color:var(--text-light)">30 marks | 2 hours | 8 questions</span></div><button class="btn btn-primary btn-sm" onclick="startMock(' + i + ')">Start</button></div>';
  }
  h += '</div>';
  el.innerHTML = h;
}

function startMock(idx) {
  currentMockTest = idx;
  mockTimeLeft = 120 * 60;
  var test = mockTests[idx];
  var h = '<div class="card"><div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap"><h2>' + test.title + '</h2><div id="mockTimer" class="timer">2:00:00</div></div><button class="btn btn-danger btn-sm" onclick="endMock()" style="margin:5px 0">End Test</button>';
  for (var s = 0; s < test.secs.length; s++) {
    var sec = test.secs[s];
    h += '<div class="mock-section"><h3>' + sec.name + '</h3>';
    for (var q = 0; q < sec.qs.length; q++) {
      h += '<div class="mock-question"><p><strong>Q' + (q+1) + '.</strong> ' + sec.qs[q].q.replace(/\n/g, '<br>') + ' <span style="color:var(--primary);font-weight:600">(' + sec.qs[q].m + ' marks)</span></p><textarea placeholder="Write your answer here..."></textarea></div>';
    }
    h += '</div>';
  }
  h += '<button class="btn btn-success" onclick="submitMock()" style="margin-top:10px">Submit Test</button></div>';
  document.getElementById('mockContainer').innerHTML = h;
  if (mockTimer) clearInterval(mockTimer);
  mockTimer = setInterval(function() {
    mockTimeLeft--;
    if (mockTimeLeft <= 0) { submitMock(); return; }
    var hrs = Math.floor(mockTimeLeft / 3600);
    var min = Math.floor((mockTimeLeft % 3600) / 60);
    var sec = mockTimeLeft % 60;
    var t = document.getElementById('mockTimer');
    if (t) {
      t.textContent = hrs + ':' + (min < 10 ? '0' : '') + min + ':' + (sec < 10 ? '0' : '') + sec;
      t.className = 'timer' + (mockTimeLeft < 300 ? ' danger' : mockTimeLeft < 600 ? ' warning' : '');
    }
  }, 1000);
}

function submitMock() {
  if (mockTimer) clearInterval(mockTimer);
  var test = mockTests[currentMockTest];
  var h = '<div class="card"><h2>Test Submitted: ' + test.title + '</h2><div class="tip"><strong>Review:</strong> Check your answers against textbook/notes.</div><h3>Topics to Revise:</h3><ul class="list">';
  for (var s = 0; s < test.secs.length; s++) {
    for (var q = 0; q < test.secs[s].qs.length; q++) {
      h += '<li>' + test.secs[s].qs[q].q.substring(0, 60) + '...</li>';
    }
  }
  h += '</ul><button class="btn btn-primary" onclick="renderMockList()" style="margin-top:10px">Back</button></div>';
  document.getElementById('mockContainer').innerHTML = h;
}

function endMock() { if (confirm('End test early?')) submitMock(); }

