function initFlashcards() { currentFlashcard = 0; renderFC(); }

function renderFC() {
  var el = document.getElementById('flashcardContainer');
  if (!el) return;
  var fc = flashcards[currentFlashcard];
  var h = '<p style="text-align:center;color:var(--text-light)">' + (currentFlashcard+1) + ' / ' + flashcards.length + '</p>';
  h += '<div class="flashcard" id="theFC" onclick="this.classList.toggle(\'flipped\')"><div class="fc-q">' + fc.q + '</div><div class="fc-a">' + fc.a + '</div></div>';
  h += '<p style="text-align:center;font-size:.85rem;color:var(--text-light)">Click card to flip</p>';
  h += '<div style="text-align:center;margin-top:10px"><button class="btn btn-outline btn-sm" onclick="prevFC()">Previous</button> <button class="btn btn-primary btn-sm" onclick="shuffleFC()">Shuffle</button> <button class="btn btn-outline btn-sm" onclick="nextFC()">Next</button></div>';
  el.innerHTML = h;
}

function nextFC() { currentFlashcard = (currentFlashcard + 1) % flashcards.length; renderFC(); }
function prevFC() { currentFlashcard = (currentFlashcard - 1 + flashcards.length) % flashcards.length; renderFC(); }
function shuffleFC() {
  for (var i = flashcards.length - 1; i > 0; i--) {
    var j = Math.floor(Math.random() * (i + 1));
    var tmp = flashcards[i]; flashcards[i] = flashcards[j]; flashcards[j] = tmp;
  }
  currentFlashcard = 0;
  renderFC();
}

