sections['revision'] = '<h1>Revision Plans</h1><div class="grid-3"><div class="card"><div class="card-header">1-Day Plan</div><h3>Morning (4 hours)</h3><ul class="list"><li>JVM, JRE, JDK, JIT (30 min)</li><li>Data Types &amp; Variables (30 min)</li><li>Type Casting (30 min)</li><li>String Methods (45 min)</li><li>Control Statements (30 min)</li><li>Break (15 min)</li></ul><h3>Afternoon (4 hours)</h3><ul class="list"><li>Arrays (30 min)</li><li>Classes &amp; Objects (30 min)</li><li>Constructors (30 min)</li><li>OOP Concepts (45 min)</li><li>Output Practice (45 min)</li><li>Programming Practice (45 min)</li></ul><h3>Evening (3 hours)</h3><ul class="list"><li>Previous Papers (1.5 hours)</li><li>Flashcards Review (30 min)</li><li>Weak Areas (1 hour)</li></ul></div><div class="card"><div class="card-header">3-Hour Plan</div><h3>Quick Revision</h3><ul class="list"><li>First 30 min: JVM/JRE/JDK + Data Types (MOST IMPORTANT)</li><li>Next 45 min: Type Casting + String Methods (MOST ASKED)</li><li>Next 45 min: OOP Concepts + Constructors</li><li>Next 30 min: Previous year questions review</li><li>Final 30 min: Output practice + weak areas</li></ul><div class="tip"><strong>Priority:</strong> JVM, String Methods, Type Casting = 70% questions come from these!</div></div><div class="card"><div class="card-header">30-Min Plan</div><h3>Last Minute</h3><ul class="list"><li>5 min: JVM/JRE/JDK differences</li><li>5 min: 8 data types with sizes</li><li>5 min: String methods key points</li><li>5 min: Integer division trap</li><li>5 min: OOP 4 pillars keywords</li><li>5 min: Constructor vs Method</li></ul><div class="tip"><strong>Focus:</strong> Ye 6 points 80% exam cover karte hain!</div></div></div>';

sections['strategy'] = '<h1>Pass Strategy &amp; Good Marks Strategy</h1><div class="grid-2"><div class="card"><div class="card-header">Pass Strategy (15+ Marks)</div><p><strong>Minimum effort to pass:</strong></p><div class="q-item"><span class="tag tag-fire">Must Do</span><p><strong>JVM, JRE, JDK, JIT</strong> - Ye 3-4 marks pakka hai. Definition + difference table likho.</p></div><div class="q-item"><span class="tag tag-fire">Must Do</span><p><strong>String Methods</strong> - substring, indexOf, equals, charAt. Code example likho.</p></div><div class="q-item"><span class="tag tag-fire">Must Do</span><p><strong>Type Casting</strong> - Implicit vs Explicit. Integer division trap.</p></div><div class="q-item"><span class="tag tag-star">Should Do</span><p><strong>Data Types</strong> - 8 primitives with sizes and defaults.</p></div><div class="q-item"><span class="tag tag-medium">If Time</span><p><strong>Output questions</strong> - Previous papers ke output practice karo.</p></div><div class="tip"><strong>Strategy:</strong> Ye 5 topics = 12-15 marks. Baaki topics se 3-5 marks aur jod lo = PASS!</div></div><div class="card"><div class="card-header">Good Marks Strategy (25+ Marks)</div><p><strong>Target: Top marks:</strong></p><div class="q-item"><span class="tag tag-fire">Priority 1</span><p>Sab Fire topics master karo (JVM, String, Type Casting)</p></div><div class="q-item"><span class="tag tag-star">Priority 2</span><p>Star topics cover karo (OOP, Variables, Control)</p></div><div class="q-item"><span class="tag tag-medium">Priority 3</span><p>Programming practice - Login, Grading, Pattern programs</p></div><div class="q-item"><span class="tag tag-medium">Priority 4</span><p>All previous papers complete karo</p></div><div class="q-item"><span class="tag tag-medium">Priority 5</span><p>Flashcards revise karo daily</p></div><div class="tip"><strong>Strategy:</strong> Daily 2 hours study. Topics aur previous papers = 25+ marks!</div></div></div>';

sections['exam-writing'] = '<h1>Exam Answer Writing Tips</h1><div class="grid-2"><div class="card"><div class="card-header">For 3-Mark Questions</div><h3>Format: Definition + Example + Key Points</h3><div class="code-block">1. Definition (1 line) - What is it?<br>2. Example or Syntax (2-3 lines)<br>3. Key points (2-3 bullet points)</div><h3>Example Answer: What is JVM?</h3><div class="tip"><strong>JVM (Java Virtual Machine)</strong> ek platform-specific virtual machine hai jo Java bytecode (.class file) ko execute karta hai.<br><br><strong>Key Points:</strong><br>- Bytecode execute karta hai<br>- Platform-specific hai (Windows, Linux ke liye alag JVM)<br>- Class Loader, Bytecode Verifier, aur Interpreter contain karta hai</div><div class="warning"><strong>Do NOT:</strong> Long paragraphs likho. Points mein likho. Examiner time ke kam hota hai.</div></div><div class="card"><div class="card-header">For 5-Mark Questions</div><h3>Format: Intro + Code + Explanation + Output</h3><div class="code-block">1. Introduction (2 lines)<br>2. Code example (5-8 lines)<br>3. Explanation (3-4 lines)<br>4. Output (1 line)</div><h3>Example Answer: Write program for grading system</h3><div class="tip"><strong>Grading System</strong> marks ke basis pe grade assign karta hai using if-else-if ladder.<br><br><strong>Program:</strong><br><code>if (marks >= 90) grade = \"A+\";<br>else if (marks >= 80) grade = \"A\";<br>else if (marks >= 70) grade = \"B\";<br>else if (marks >= 60) grade = \"C\";<br>else if (marks >= 50) grade = \"D\";<br>else grade = \"Fail\";</code><br><br><strong>Output:</strong> For marks=75, output is Grade: B</div><div class="warning"><strong>Do NOT:</strong> Sirf code likho bina explanation ke. Explanation zarur do - examiner ko samajhna chahiye tumhe aata hai.</div></div></div><div class="card"><h2>General Tips</h2><ul class="list"><li><strong>Presentation:</strong> Points mein likho, paragraphs mein nahi</li><li><strong>Diagrams:</strong> JVM/JRE/JDK diagram agar bana sako toh banao</li><li><strong>Code Format:</strong> Proper indentation rakho, variables meaningful naam do</li><li><strong>Output:</strong> Output zarur likho - code ke baad</li><li><strong>Common Mistakes:</strong> Integer division trap zarur mention karo agar casting question ho</li><li><strong>Time Management:</strong> Pehle 3-mark questions karo (Section A), phir 5-mark (Section B)</li><li><strong>Revision:</strong> Last 5 min mein answers check karo - especially output questions</li></ul><div class="tip"><strong>Golden Rule:</strong> Pehle sab questions padho. Jo sabse aasan lage usse shuru karo. Time management is key!</div></div>';
